import { useEffect, useRef } from "react";
import Icon from "./Icon";

export default function Modal({ title, subtitle, children, onClose, wide = false }) {
	const dialog = useRef(null);
	useEffect(() => {
		const node = dialog.current;
		const previous = document.activeElement;
		node.showModal();
		return () => {
			node.close();
			previous?.focus?.();
		};
	}, []);
	return (
		<dialog
			ref={dialog}
			className={`modal ${wide ? "wide" : ""}`}
			onCancel={(event) => {
				event.preventDefault();
				onClose();
			}}
			onClick={(event) => {
				if (event.target === event.currentTarget) onClose();
			}}
			aria-labelledby="modal-title"
		>
			<div className="modal-header">
				<div>
					<h2 id="modal-title">{title}</h2>
					{subtitle && <p>{subtitle}</p>}
				</div>
				<button className="icon-button" aria-label="Close dialog" onClick={onClose}>
					<Icon name="close" />
				</button>
			</div>
			{children}
		</dialog>
	);
}
import { initials, statusLabel } from "../utils/format";
import Icon from "./Icon";

export function Avatar({ user, name, size = "", color = "" }) {
	const label = user?.name || user?.full_name || name || "Team member";
	return (
		<span className={`avatar ${size} ${color || user?.color || ""}`} title={label}>
			{initials(label)}
		</span>
	);
}
export function AvatarStack({ users = [], limit = 3 }) {
	return (
		<div className="avatar-stack">
			{users.slice(0, limit).map((user, index) => (
				<Avatar key={user.id || index} user={user} size="small" color={["peach", "lavender", "mint"][index % 3]} />
			))}
			{users.length > limit && <span className="avatar small extra">+{users.length - limit}</span>}
		</div>
	);
}
export function Badge({ status, children }) {
	return (
		<span className={`badge ${status || ""}`}>
			<span className="status-dot" />
			{children || statusLabel(status)}
		</span>
	);
}
export function EmptyState({ title = "Nothing here yet", children, action }) {
	return (
		<div className="empty-state">
			<span className="empty-icon">
				<Icon name="layers" size={26} />
			</span>
			<h3>{title}</h3>
			{children && <p>{children}</p>}
			{action}
		</div>
	);
}
export function LoadingState({ label = "Loading your workspace…" }) {
	return (
		<div className="loading-state" role="status">
			<span className="spinner" />
			<p>{label}</p>
		</div>
	);
}
export function ErrorState({ error, retry }) {
	return (
		<div className="error-state" role="alert">
			<Icon name="help" />
			<div>
				<strong>Something needs a second look</strong>
				<p>{error?.message || String(error)}</p>
			</div>
			{retry && (
				<button className="button secondary" onClick={retry}>
					Try again
				</button>
			)}
		</div>
	);
}
export function SectionHeading({ title, subtitle, action }) {
	return (
		<div className="section-heading">
			<div>
				<h2>{title}</h2>
				{subtitle && <p>{subtitle}</p>}
			</div>
			{action}
		</div>
	);
}
export function FormField({ label, children, hint }) {
	return (
		<label className="form-field">
			<span>{label}</span>
			{children}
			{hint && <small>{hint}</small>}
		</label>
	);
}
import { useRef } from "react";
import Icon from "../../shared/components/Icon";

export default function AssetPreview({ asset, version, onAnchor, anchor, current }) {
	const copyRef = useRef(null);
	const content = version?.content ?? asset.content;
	const media = version?.mediaPath || asset.mediaPath || asset.thumbnail;
	function selectText() {
		if (!current) return;
		const selection = window.getSelection();
		if (
			!selection ||
			selection.isCollapsed ||
			!copyRef.current?.contains(selection.anchorNode) ||
			!copyRef.current?.contains(selection.focusNode)
		)
			return;
		const range = selection.getRangeAt(0);
		const prefix = range.cloneRange();
		prefix.selectNodeContents(copyRef.current);
		prefix.setEnd(range.startContainer, range.startOffset);
		const start = Array.from(prefix.toString()).length;
		onAnchor({ type: "text", start, end: start + Array.from(range.toString()).length, label: range.toString().slice(0, 75) });
	}
	function selectPoint(event) {
		if (!current) return;
		const bounds = event.currentTarget.getBoundingClientRect();
		onAnchor({
			type: "image",
			x: Number(((event.clientX - bounds.left) / bounds.width).toFixed(4)),
			y: Number(((event.clientY - bounds.top) / bounds.height).toFixed(4)),
			label: "Point on image",
		});
	}
	return (
		<section
			className={`asset-preview ${asset.type === "image" ? "visual-preview" : ""}`}
			aria-label={`Preview of ${asset.title}, version ${version?.number || asset.version}`}
		>
			<div className="preview-toolbar">
				<span>
					<Icon name={asset.type === "image" ? "image" : "file"} size={16} />
					{asset.type === "image" ? "Visual asset" : "Copy document"}
					<span>·</span>Version {version?.number || asset.version}
				</span>
				<span className="preview-hint">
					{current
						? asset.type === "image"
							? "Click the visual to pin feedback"
							: "Select text to anchor feedback"
						: "Previous version · read only"}
				</span>
			</div>
			{asset.type === "image" ? (
				<div className="visual-canvas">
					<button className="image-anchor-area" disabled={!current} onClick={selectPoint} aria-label="Pin feedback on image">
						<img src={media} alt={asset.title} />
						{anchor?.type === "image" && (
							<span className="annotation-pin" style={{ left: `${anchor.x * 100}%`, top: `${anchor.y * 100}%` }}>
								<Icon name="message" size={13} />
							</span>
						)}
					</button>
					<p>Thoughtful details make all the difference.</p>
				</div>
			) : (
				<div className="copy-canvas">
					<div className="copy-paper">
						<span className="copy-kicker">{asset.projectName} / COPY REVIEW</span>
						<h2>{version?.title || asset.title}</h2>
						<div ref={copyRef} className="copy-content" onMouseUp={selectText} onKeyUp={selectText}>
							{content || "This draft is waiting for its first words."}
						</div>
						<div className="paper-bottom">
							<span>REVIEWROOM</span>
							<span>v{version?.number || asset.version}</span>
						</div>
					</div>
				</div>
			)}
		</section>
	);
}
import { useState } from "react";
import Icon from "../../shared/components/Icon";
import { Avatar, EmptyState } from "../../shared/components/Primitives";
import { relativeTime } from "../../shared/utils/format";

function Thread({ thread, mutate, canResolve, current }) {
	const [reply, setReply] = useState("");
	const [replying, setReplying] = useState(false);
	const [busy, setBusy] = useState(false);
	const [error, setError] = useState("");
	async function send(event) {
		event.preventDefault();
		setBusy(true);
		setError("");
		try {
			await mutate(`/comments/${thread.id}/replies`, "POST", { body: reply });
			setReply("");
			setReplying(false);
		} catch (failure) {
			setError(failure.message);
		} finally {
			setBusy(false);
		}
	}
	async function resolve() {
		setBusy(true);
		setError("");
		try {
			await mutate(`/comments/${thread.id}`, "PATCH", { resolved: !thread.resolved });
		} catch (failure) {
			setError(failure.message);
		} finally {
			setBusy(false);
		}
	}
	return (
		<article className={`thread ${thread.resolved ? "resolved" : ""}`}>
			<div className="thread-header">
				<Avatar user={thread.author} size="small" color="lavender" />
				<div>
					<strong>{thread.author?.name}</strong>
					<small>{relativeTime(thread.createdAt)}</small>
				</div>
				{canResolve && current && (
					<button
						className={`icon-button ${thread.resolved ? "is-resolved" : ""}`}
						aria-label={thread.resolved ? "Reopen feedback" : "Resolve feedback"}
						title={thread.resolved ? "Reopen feedback" : "Resolve feedback"}
						onClick={resolve}
						disabled={busy}
					>
						<Icon name="check" size={16} />
					</button>
				)}
			</div>
			{["image", "text"].includes(thread.anchor?.type) && (
				<div className="thread-anchor">
					<Icon name={thread.anchor.type === "image" ? "image" : "file"} size={13} />
					{thread.anchor.type === "image"
						? `Image pin · ${Math.round(thread.anchor.x * 100)}%, ${Math.round(thread.anchor.y * 100)}%`
						: `Selected text · characters ${thread.anchor.start}–${thread.anchor.end}`}
				</div>
			)}
			<p className="thread-body">{thread.body}</p>
			{thread.resolved && (
				<span className="resolved-label">
					<Icon name="check" size={12} />
					Resolved
				</span>
			)}
			{thread.replies?.map((replyItem) => (
				<div className="thread-reply" key={replyItem.id}>
					<Avatar user={replyItem.author} size="tiny" color="peach" />
					<div>
						<strong>{replyItem.author?.name}</strong>
						<p>{replyItem.body}</p>
						<small>{relativeTime(replyItem.createdAt)}</small>
					</div>
				</div>
			))}
			{!replying && current && (
				<button className="text-button thread-reply-button" onClick={() => setReplying(true)}>
					Reply to thread
				</button>
			)}
			{replying && (
				<form className="thread-reply-form" onSubmit={send}>
					<label className="sr-only" htmlFor={`reply-${thread.id}`}>
						Your reply
					</label>
					<textarea
						id={`reply-${thread.id}`}
						value={reply}
						autoFocus
						required
						maxLength={4000}
						onChange={(event) => setReply(event.target.value)}
						rows={2}
						placeholder="Add your thoughts…"
					/>
					<div>
						<button className="text-button" type="button" onClick={() => setReplying(false)}>
							Cancel
						</button>
						<button className="button primary small" disabled={busy}>
							{busy ? "Sending…" : "Reply"}
						</button>
					</div>
				</form>
			)}
			{error && (
				<p className="form-error" role="alert">
					{error}
				</p>
			)}
		</article>
	);
}
export default function Threads({ asset, version, anchor, setAnchor, mutate, user, writable = true }) {
	const [body, setBody] = useState("");
	const [filter, setFilter] = useState("open");
	const [busy, setBusy] = useState(false);
	const [error, setError] = useState("");
	const current = version === asset.version && writable;
	const comments = (asset.comments || []).filter((thread) => thread.version === version);
	const visible = comments.filter((thread) => filter === "all" || !thread.resolved);
	async function comment(event) {
		event.preventDefault();
		setBusy(true);
		setError("");
		try {
			const { label: _label, ...coordinates } = anchor || {};
			await mutate("/comments", "POST", { version, body, ...(anchor ? { anchor: coordinates } : {}) });
			setBody("");
			setAnchor(null);
		} catch (failure) {
			setError(failure.message);
		} finally {
			setBusy(false);
		}
	}
	return (
		<>
			<div className="feedback-filter">
				<span>{comments.filter((thread) => !thread.resolved).length} open threads</span>
				<select aria-label="Filter feedback threads" value={filter} onChange={(event) => setFilter(event.target.value)}>
					<option value="open">Open</option>
					<option value="all">All feedback</option>
				</select>
			</div>
			<div className="thread-list">
				{visible.map((thread) => (
					<Thread
						key={thread.id}
						thread={thread}
						mutate={mutate}
						canResolve={asset.canEdit || user.role === "owner" || thread.author?.id === user.id}
						current={current}
					/>
				))}
				{!visible.length && (
					<EmptyState title={filter === "open" ? "A little space for feedback." : "No feedback on this version."}>
						{current
							? "Share a thought below, or select part of the work to be more specific."
							: "Feedback stays connected to the version it was left on."}
					</EmptyState>
				)}
			</div>
			{current ? (
				<form className="comment-composer" onSubmit={comment}>
					{anchor && (
						<div className="selected-anchor">
							<Icon name="link" size={14} />
							<span>{anchor.label || "Anchored feedback"}</span>
							<button
								className="icon-button"
								aria-label="Remove feedback anchor"
								type="button"
								onClick={() => setAnchor(null)}
							>
								<Icon name="close" size={13} />
							</button>
						</div>
					)}
					<div className="composer-top">
						<Avatar user={user} size="small" color="peach" />
						<label className="sr-only" htmlFor="new-comment">
							Add feedback
						</label>
						<textarea
							id="new-comment"
							value={body}
							onChange={(event) => setBody(event.target.value)}
							required
							rows={3}
							placeholder="A thought, a question, a little clarity…"
							maxLength={4000}
						/>
					</div>
					{error && (
						<p className="form-error" role="alert">
							{error}
						</p>
					)}
					<div className="composer-bottom">
						<small>Keep it thoughtful.</small>
						<button className="button primary small" disabled={busy || !body.trim()}>
							{busy ? "Posting…" : "Post feedback"}
							<Icon name="arrow" size={14} />
						</button>
					</div>
				</form>
			) : (
				<p className="past-version-note">
					<Icon name="clock" size={15} />
					{writable
						? "You’re viewing feedback on a previous version. Switch to the latest version to add a comment."
						: "This project is archived. Feedback is kept here for reference."}
				</p>
			)}
		</>
	);
}
