import { useEffect, useState } from "react";
import { api, download, queryString } from "../../shared/api/client";
import useResource from "../../shared/api/useResource";
import Icon from "../../shared/components/Icon";
import { ErrorState, LoadingState } from "../../shared/components/Primitives";
import Modal from "../../shared/components/Modal";
import AssetTable from "./AssetTable";

export default function Assets({
	user,
	people,
	projects,
	navigate,
	onCreate,
	search = "",
	setSearch,
	query = "",
	projectId,
	refreshKey,
	notify,
	reviews = false,
}) {
	const [filters, setFilters] = useState(() => ({
		status: new URLSearchParams(query).get("status") || "",
		overdue: new URLSearchParams(query).get("overdue") || "",
		projectId: projectId || "",
		sort: "updated",
	}));
	const [page, setPage] = useState(1);
	const [debouncedSearch, setDebouncedSearch] = useState(search);
	useEffect(() => {
		const timer = setTimeout(() => setDebouncedSearch(search), 250);
		return () => clearTimeout(timer);
	}, [search]);
	const [saveOpen, setSaveOpen] = useState(false);
	const [viewName, setViewName] = useState("");
	const [saving, setSaving] = useState(false);
	const [saveError, setSaveError] = useState("");
	useEffect(() => {
		setFilters((previous) => ({
			...previous,
			status: new URLSearchParams(query).get("status") || "",
			overdue: new URLSearchParams(query).get("overdue") || "",
			projectId: projectId || "",
		}));
		setPage(1);
	}, [query, projectId]);
	useEffect(() => setPage(1), [debouncedSearch]);
	const activeFilters = { ...filters, q: debouncedSearch, ...(reviews ? { assigneeId: user.id } : {}), page, pageSize: 12 };
	const resource = useResource(`/assets?${queryString(activeFilters)}`, null, refreshKey);
	const savedViews = useResource("/saved-views", [], refreshKey);
	const update = (key, value) => {
		setFilters((previous) => ({ ...previous, [key]: value }));
		setPage(1);
	};
	async function saveView(event) {
		event.preventDefault();
		setSaving(true);
		setSaveError("");
		try {
			await api("/saved-views", {
				method: "POST",
				body: { name: viewName, filters: { ...filters, q: search, ...(reviews ? { assigneeId: user.id } : {}) } },
			});
			savedViews.refresh();
			setSaveOpen(false);
			setViewName("");
			notify("Your view is saved. One less thing to find.");
		} catch (error) {
			setSaveError(error.message);
		} finally {
			setSaving(false);
		}
	}
	async function exportCsv() {
		try {
			await download(`/reports/export.csv?${queryString({ ...activeFilters, q: search })}`, "reviewroom-assets.csv");
			notify("Your asset report is ready.");
		} catch (error) {
			notify(error.message, "error");
		}
	}
	return (
		<>
			{!projectId && (
				<div className="page-heading">
					<div>
						<p className="eyebrow">{reviews ? "A FRESH PAIR OF EYES" : "EVERY PIECE OF THE BIGGER PICTURE"}</p>
						<h1>
							{reviews ? "Your feedback makes a difference" : "All your good work, together"}
							<span className="heading-star">✳</span>
						</h1>
						<p>
							{reviews
								? "The work waiting for your thoughtful review."
								: "From first draft to final approval. Nothing lost along the way."}
						</p>
					</div>
					{user.role !== "reviewer" && (
						<button className="button primary" onClick={onCreate}>
							<Icon name="plus" size={18} />
							New asset
						</button>
					)}
				</div>
			)}
			<div className="asset-filters">
				<div className="filter-group">
					<label>
						<span className="sr-only">Status</span>
						<select value={filters.status} onChange={(event) => update("status", event.target.value)}>
							<option value="">All statuses</option>
							<option value="draft">Draft</option>
							<option value="in_review">In review</option>
							<option value="changes_requested">Changes requested</option>
							<option value="approved">Approved</option>
						</select>
					</label>
					{!projectId && (
						<label>
							<span className="sr-only">Project</span>
							<select value={filters.projectId} onChange={(event) => update("projectId", event.target.value)}>
								<option value="">All projects</option>
								{projects.map((project) => (
									<option key={project.id} value={project.id}>
										{project.name}
									</option>
								))}
							</select>
						</label>
					)}
					<button
						className={`button filter-button ${filters.overdue ? "selected" : ""}`}
						aria-pressed={Boolean(filters.overdue)}
						onClick={() => update("overdue", filters.overdue ? "" : "true")}
					>
						<Icon name="clock" size={15} />
						Overdue
					</button>
				</div>
				<div className="filter-group">
					<label>
						<span className="sr-only">Sort assets</span>
						<select value={filters.sort} onChange={(event) => update("sort", event.target.value)}>
							<option value="updated">Recently updated</option>
							<option value="due">Due date</option>
							<option value="title">Asset name</option>
						</select>
					</label>
					<button className="icon-button bordered" aria-label="Save current filters as a view" onClick={() => setSaveOpen(true)}>
						<Icon name="filter" size={18} />
					</button>
					<button className="icon-button bordered" aria-label="Export filtered assets as CSV" onClick={exportCsv}>
						<Icon name="download" size={18} />
					</button>
				</div>
			</div>
			{savedViews.data?.length > 0 && (
				<div className="saved-views">
					<span>YOUR VIEWS</span>
					{savedViews.data.map((view) => (
						<span className="saved-view" key={view.id}>
							<button
								onClick={() => {
									setFilters({
										status: "",
										overdue: "",
										sort: "updated",
										...view.filters,
										projectId: projectId || view.filters.projectId || "",
									});
									setSearch?.(view.filters.q || "");
									setPage(1);
								}}
							>
								{view.name}
							</button>
							<button
								aria-label={`Delete saved view ${view.name}`}
								onClick={async () => {
									try {
										await api(`/saved-views/${view.id}`, { method: "DELETE" });
										savedViews.refresh();
									} catch (error) {
										notify(error.message, "error");
									}
								}}
							>
								<Icon name="close" size={12} />
							</button>
						</span>
					))}
				</div>
			)}
			<section className="panel assets-panel">
				{resource.loading ? (
					<LoadingState label="Finding your good work…" />
				) : resource.error ? (
					<ErrorState error={resource.error} retry={resource.refresh} />
				) : (
					<>
						<AssetTable assets={resource.data?.items} people={people} onOpen={(id) => navigate(`asset/${id}`)} />
						<div className="table-pagination">
							<span>
								{resource.data?.total || 0} assets{" "}
								<span className="muted">
									· Page {page} of {Math.max(1, Math.ceil((resource.data?.total || 0) / 12))}
								</span>
							</span>
							<div>
								<button
									className="button secondary small"
									disabled={page <= 1}
									onClick={() => setPage((value) => value - 1)}
								>
									Previous
								</button>
								<button
									className="button secondary small"
									disabled={page * 12 >= (resource.data?.total || 0)}
									onClick={() => setPage((value) => value + 1)}
								>
									Next
								</button>
							</div>
						</div>
					</>
				)}
			</section>
			{saveOpen && (
				<Modal
					title="Keep this view handy"
					subtitle="Save these filters for the next time you need them."
					onClose={() => setSaveOpen(false)}
				>
					<form onSubmit={saveView}>
						<div className="modal-body">
							<label className="form-field">
								<span>View name</span>
								<input
									autoFocus
									value={viewName}
									required
									maxLength={80}
									onChange={(event) => setViewName(event.target.value)}
									placeholder="e.g. This week’s reviews"
								/>
							</label>
							{saveError && (
								<p className="form-error" role="alert">
									{saveError}
								</p>
							)}
						</div>
						<div className="modal-footer">
							<button className="button secondary" type="button" onClick={() => setSaveOpen(false)}>
								Cancel
							</button>
							<button className="button primary" disabled={saving}>
								{saving ? "Saving…" : "Save view"}
							</button>
						</div>
					</form>
				</Modal>
			)}
		</>
	);
}
import { useState } from "react";
import { api } from "../../shared/api/client";
import Icon from "../../shared/components/Icon";
import { EmptyState } from "../../shared/components/Primitives";
import { relativeTime } from "../../shared/utils/format";

export default function Inbox({ items = [], navigate, onChanged, notify, user }) {
	const [unreadOnly, setUnreadOnly] = useState(false);
	const [busy, setBusy] = useState(false);
	const visible = items.filter((item) => !unreadOnly || !item.read);
	async function markRead(item) {
		if (item.read) return;
		try {
			await api(`/inbox/${item.id}`, { method: "PATCH", body: { read: true } });
			onChanged();
		} catch (error) {
			notify(error.message, "error");
		}
	}
	async function reminders() {
		setBusy(true);
		try {
			const result = await api("/reminders/process", { method: "POST" });
			onChanged();
			notify(`${result?.created || 0} review reminders prepared.`);
		} catch (error) {
			notify(error.message, "error");
		} finally {
			setBusy(false);
		}
	}
	return (
		<>
			<div className="page-heading">
				<div>
					<p className="eyebrow">KEEP A LITTLE ROOM IN THE LOOP</p>
					<h1>
						A note for you<span className="heading-star">✳</span>
					</h1>
					<p>Reviews, replies, and the next small thing that needs your attention.</p>
				</div>
				{user.role === "owner" && (
					<button className="button secondary" disabled={busy} onClick={reminders}>
						<Icon name="bell" size={17} />
						{busy ? "Preparing…" : "Process reminders"}
					</button>
				)}
			</div>
			<div className="tabs inbox-tabs">
				<button className={!unreadOnly ? "active" : ""} onClick={() => setUnreadOnly(false)}>
					All updates <span>{items.length}</span>
				</button>
				<button className={unreadOnly ? "active" : ""} onClick={() => setUnreadOnly(true)}>
					Unread <span>{items.filter((item) => !item.read).length}</span>
				</button>
			</div>
			<section className="panel inbox-panel">
				{visible.map((item) => (
					<article className={`inbox-item ${item.read ? "" : "unread"}`} key={item.id}>
						<span className="inbox-symbol">
							<Icon name={item.title.toLowerCase().includes("approv") ? "check" : "message"} size={20} />
						</span>
						<div>
							<button
								className="inbox-title"
								onClick={() => {
									markRead(item);
									if (item.assetId) navigate(`asset/${item.assetId}`);
								}}
							>
								{item.title}
							</button>
							<p>{item.body}</p>
							<small>{relativeTime(item.createdAt)}</small>
						</div>
						{!item.read && (
							<button className="icon-button" aria-label={`Mark ${item.title} as read`} onClick={() => markRead(item)}>
								<Icon name="check" size={17} />
							</button>
						)}
					</article>
				))}
				{!visible.length && (
					<EmptyState title="You’re all caught up.">A little quiet is a good thing. We’ll keep you in the loop.</EmptyState>
				)}
			</section>
		</>
	);
}
import { download } from "../../shared/api/client";
import useResource from "../../shared/api/useResource";
import Icon from "../../shared/components/Icon";
import { Avatar, ErrorState, LoadingState, SectionHeading } from "../../shared/components/Primitives";
import { dateLabel } from "../../shared/utils/format";

export default function Reports({ navigate, refreshKey, notify }) {
	const resource = useResource("/reports", null, refreshKey);
	if (resource.loading) return <LoadingState label="Putting the progress in perspective…" />;
	if (resource.error) return <ErrorState error={resource.error} retry={resource.refresh} />;
	const { summary, byProject = [], workload = [], trend = [] } = resource.data;
	const maxTrend = Math.max(1, ...trend.map((day) => day.approvals));
	async function exportReport() {
		try {
			await download("/reports/export.csv", "reviewroom-workspace-report.csv");
			notify("Your workspace report is ready.");
		} catch (error) {
			notify(error.message, "error");
		}
	}
	return (
		<>
			<div className="page-heading">
				<div>
					<p className="eyebrow">THE BIGGER PICTURE</p>
					<h1>
						Good work adds up<span className="heading-star">✳</span>
					</h1>
					<p>A clear view of your progress, your process, and your people.</p>
				</div>
				<button className="button secondary" onClick={exportReport}>
					<Icon name="download" size={17} />
					Export report
				</button>
			</div>
			<div className="dashboard-stats report-stats">
				{[
					["Total assets", summary.totalAssets, "Every piece of the work"],
					["Approval rate", `${summary.approvalRate}%`, "Assets with every stage approved"],
					["Average review cycle", `${summary.averageCycleHours}h`, "Submission to final approval"],
					["Awaiting review", summary.inReview, `${summary.overdue} overdue reviews`],
				].map(([label, value, description]) => (
					<div className="stat-card" key={label}>
						<div className="stat-label">
							{label}
							<Icon name="chart" size={16} />
						</div>
						<strong>{value}</strong>
						<small>{description}</small>
					</div>
				))}
			</div>
			<div className="reports-grid">
				<section className="panel report-projects">
					<SectionHeading title="Progress by project" subtitle="Small steps toward a shared finish line." />
					<div className="project-report-list">
						{byProject.map((project) => (
							<button key={project.id} onClick={() => navigate(`project/${project.id}`)}>
								<div>
									<strong>{project.name}</strong>
									<span>
										{project.approved} / {project.total} approved
									</span>
								</div>
								<div className="progress-track">
									<span
										style={{
											width: `${project.total ? (project.approved / project.total) * 100 : 0}%`,
											background: project.color,
										}}
									/>
								</div>
								<small>
									{project.inReview} in review <span>·</span> {project.overdue} overdue
								</small>
							</button>
						))}
					</div>
				</section>
				<section className="panel report-trend">
					<SectionHeading title="A week of forward motion" subtitle="Recorded approvals over the last 7 days." />
					<div
						className="trend-chart"
						role="img"
						aria-label={`Daily approvals: ${trend.map((day) => `${dateLabel(day.date)}, ${day.approvals}`).join("; ")}`}
					>
						{trend.map((day) => (
							<div className="trend-column" key={day.date}>
								<strong>{day.approvals}</strong>
								<div className="trend-bar-track">
									<span style={{ height: `${Math.max(3, (day.approvals / maxTrend) * 100)}%` }} />
								</div>
								<small>{new Date(`${day.date}T12:00:00`).toLocaleDateString("en-US", { weekday: "short" })}</small>
							</div>
						))}
					</div>
					<p className="chart-note">Every yes moves a good idea forward.</p>
				</section>
			</div>
			<section className="panel workload-panel">
				<SectionHeading
					title="The people behind the progress"
					subtitle="Current stage assignments that are still waiting for a decision."
				/>
				<div className="workload-grid">
					{workload.map((item) => (
						<div className="workload-card" key={item.reviewer.id}>
							<Avatar user={item.reviewer} color="lavender" />
							<div>
								<strong>{item.reviewer.name}</strong>
								<small>{item.reviewer.role}</small>
							</div>
							<span>
								<strong>{item.assigned}</strong>
								<small>assigned</small>
							</span>
							<span className={item.overdue ? "overdue" : "muted"}>{item.overdue} overdue</span>
						</div>
					))}
				</div>
			</section>
		</>
	);
}
import { useState } from "react";
import { api, setToken } from "../../shared/api/client";
import Icon from "../../shared/components/Icon";
import { FormField } from "../../shared/components/Primitives";

export default function Login({ onLogin }) {
	const [email, setEmail] = useState("owner@reviewroom.test");
	const [password, setPassword] = useState("Reviewroom2026!");
	const [busy, setBusy] = useState(false);
	const [error, setError] = useState("");
	async function submit(event) {
		event.preventDefault();
		setBusy(true);
		setError("");
		try {
			const result = await api("/auth/login", { method: "POST", body: { email, password } });
			setToken(result.token);
			onLogin(result.user);
		} catch (failure) {
			setError(failure.message);
		} finally {
			setBusy(false);
		}
	}
	return (
		<main className="login-page">
			<section className="login-story">
				<a className="brand" href="#">
					<span className="brand-mark">
						r<span>•</span>
					</span>
					reviewroom<span className="brand-dot">.</span>
				</a>
				<div>
					<p className="eyebrow">A LITTLE CLARITY. A LOT OF GOOD WORK.</p>
					<h1>
						Great ideas deserve
						<br />
						<em>a clear way forward.</em>
					</h1>
					<p>Bring your creative work, thoughtful feedback, and final approvals into one shared space.</p>
					<div className="login-art">
						<img src="/assets/botanica.svg" alt="Botanica campaign artwork with sculptural green leaves" />
						<span className="login-approved">
							<Icon name="check" size={16} /> A little closer to approved.
						</span>
					</div>
				</div>
				<small>Made for teams who care about the details.</small>
			</section>
			<section className="login-form-wrap">
				<form className="login-form" onSubmit={submit}>
					<span className="pill">YOUR CREATIVE HQ</span>
					<h2>Good to have you here.</h2>
					<p>Sign in to your Reviewroom workspace.</p>
					<FormField label="Email address">
						<input
							type="email"
							value={email}
							onChange={(event) => setEmail(event.target.value)}
							required
							autoComplete="username"
						/>
					</FormField>
					<FormField label="Password">
						<input
							type="password"
							value={password}
							onChange={(event) => setPassword(event.target.value)}
							required
							autoComplete="current-password"
						/>
					</FormField>
					{error && (
						<p role="alert" className="form-error">
							{error}
						</p>
					)}
					<button className="button primary full" disabled={busy}>
						{busy ? "Signing in…" : "Enter your workspace"}
						<Icon name="arrow" size={18} />
					</button>
					<div className="demo-access">
						<strong>Take a look around</strong>
						<p>
							Seeded demo accounts share the password <code>Reviewroom2026!</code>
						</p>
						<div>
							{["owner", "editor", "reviewer"].map((role) => (
								<button
									type="button"
									className={email.startsWith(role) ? "active" : ""}
									key={role}
									onClick={() => {
										setEmail(`${role}@reviewroom.test`);
										setPassword("Reviewroom2026!");
									}}
								>
									{role}
								</button>
							))}
						</div>
					</div>
				</form>
				<p className="login-footnote">Feedback feels better when it’s all in one place.</p>
			</section>
		</main>
	);
}
