		content = (
			<ErrorState
				error={projects.error || people.error}
				retry={() => {
					projects.refresh();
					people.refresh();
				}}
			/>
		);
	else if (page === "overview") content = <Dashboard {...common} onCreate={() => setModal({ type: "project" })} />;
	else if (page === "projects") content = <Projects {...common} onCreate={() => setModal({ type: "project" })} />;
	else if (page === "project") content = <ProjectDetail {...common} key={id} id={id} onCreate={createAsset} onChanged={changed} />;
	else if (page === "assets" || page === "reviews")
		content = (
			<Assets {...common} key={page} search={search} query={query} reviews={page === "reviews"} onCreate={() => createAsset("")} />
		);
	else if (page === "asset") content = <AssetDetail {...common} key={id} id={id} onChanged={changed} />;
	else if (page === "inbox")
		content = inbox.error ? (
			<ErrorState error={inbox.error} retry={inbox.refresh} />
		) : (
			<Inbox {...common} items={inbox.data || []} onChanged={changed} />
		);
	else if (page === "reports") content = <Reports {...common} />;
	else content = <Guide />;
	return (
		<>
			<Shell
				user={user}
				page={page}
				navigate={navigate}
				unread={inbox.data?.filter((item) => !item.read).length || 0}
				search={search}
				setSearch={setSearch}
				onLogout={logout}
			>
				<ScreenBoundary key={routePath}>
					<Suspense fallback={<LoadingState />}>{content}</Suspense>
				</ScreenBoundary>
			</Shell>
			<Suspense
				fallback={
					<div className="toast" role="status">
						Opening form…
					</div>
				}
			>
				{modal?.type === "project" && (
					<ProjectForm
						people={people.data || []}
						user={user}
						onClose={() => setModal(null)}
						onSaved={(project) => {
							setModal(null);
							changed();
							navigate(`project/${project.id}`);
							notify("A new room for good work. Your project is ready.");
						}}
					/>
				)}
				{modal?.type === "asset" && (
					<AssetForm
						projects={projects.data || []}
						projectId={modal.projectId}
						people={people.data || []}
						user={user}
						onClose={() => setModal(null)}
						onSaved={(asset) => {
							setModal(null);
							changed();
							navigate(`asset/${asset.id}`);
							notify("Your first draft is in. Let’s make it a good one.");
						}}
					/>
				)}
			</Suspense>
			{toast && (
				<div className={`toast ${toast.type}`} role="status">
					<Icon name={toast.type === "error" ? "help" : "check"} size={18} />
					<span>{toast.message}</span>
					<button className="icon-button" aria-label="Dismiss notification" onClick={() => setToast(null)}>
						<Icon name="close" size={15} />
					</button>
				</div>
			)}
		</>
	);
}
import useResource from "../../shared/api/useResource";
import Icon from "../../shared/components/Icon";
import { Avatar, ErrorState, LoadingState, SectionHeading, EmptyState } from "../../shared/components/Primitives";
import { relativeTime } from "../../shared/utils/format";
import ProjectCard from "../projects/ProjectCard";
import AssetTable from "../assets/AssetTable";

export default function Dashboard({ user, projects, people, navigate, onCreate, refreshKey }) {
	const reports = useResource("/reports", null, refreshKey);
	const assets = useResource("/assets?pageSize=100&sort=due", null, refreshKey);
	const activity = useResource("/activity", [], refreshKey);
	if (reports.loading || assets.loading) return <LoadingState />;
	if (reports.error || assets.error)
		return (
			<ErrorState
				error={reports.error || assets.error}
				retry={() => {
					reports.refresh();
					assets.refresh();
				}}
			/>
		);
	const summary = reports.data?.summary || {};
	const items = assets.data?.items || [];
	const reviewQueue = items.filter((asset) => ["in_review", "changes_requested"].includes(asset.status)).slice(0, 4);
	const deadlines = items
		.filter((asset) => asset.dueAt && asset.status !== "approved")
		.sort((first, second) => new Date(first.dueAt).getTime() - new Date(second.dueAt).getTime())
		.slice(0, 3);
	const stats = [
		["folder", "Active projects", projects.filter((project) => !project.archived).length, "Good things in motion", "violet"],
		["review", "Awaiting review", summary.inReview || 0, "Ready for a fresh pair of eyes", "amber"],
		["check", "Approved assets", summary.approved || 0, "One step closer to out there", "green"],
		["clock", "Overdue reviews", summary.overdue || 0, "A gentle nudge might help", "rose"],
	];
	return (
		<>
			<div className="page-heading">
				<div>
					<p className="eyebrow">YOUR WORK, IN A GOOD PLACE</p>
					<h1>
						Let’s make good things happen<span className="heading-star">✳</span>
					</h1>
					<p>Welcome back, {user.name.split(" ")[0]}. Here’s what’s moving in your workspace.</p>
				</div>
				{user.role !== "reviewer" && (
					<button className="button primary" onClick={onCreate}>
						<Icon name="plus" size={18} />
						New project
					</button>
				)}
			</div>
			<div className="dashboard-stats">
				{stats.map(([icon, label, value, description, color]) => (
					<button
						key={label}
						className="stat-card"
						onClick={() =>
							navigate(
								label === "Active projects"
									? "projects"
									: `assets${label === "Awaiting review" ? "?status=in_review" : label === "Approved assets" ? "?status=approved" : "?overdue=true"}`,
							)
						}
					>
						<div className="stat-label">
							<span>{label}</span>
							<span className={`stat-icon ${color}`}>
								<Icon name={icon} size={18} />
							</span>
						</div>
						<strong>{value}</strong>
						<small>{description}</small>
					</button>
				))}
			</div>
			<section className="projects-section">
				<SectionHeading
					title="Projects in motion"
					subtitle="A little progress, every day."
					action={
						<button className="text-button" onClick={() => navigate("projects")}>
							All projects
							<Icon name="arrow" size={15} />
						</button>
					}
				/>
				<div className="project-grid dashboard-projects">
					{projects
						.filter((project) => !project.archived)
						.slice(0, 3)
						.map((project) => (
							<ProjectCard key={project.id} project={project} people={people} onOpen={(id) => navigate(`project/${id}`)} />
						))}
				</div>
				{!projects.length && (
					<EmptyState
						title="Make room for your first project."
						action={
							<button className="button primary" onClick={onCreate}>
								New project
							</button>
						}
					/>
				)}
			</section>
			<div className="dashboard-bottom">
				<section className="panel review-panel">
					<SectionHeading
						title="Ready for a closer look"
						subtitle="These assets could use your thoughtful feedback."
						action={
							<button className="text-button" onClick={() => navigate("reviews")}>
								View all
								<Icon name="arrow" size={15} />
							</button>
						}
					/>
					<AssetTable assets={reviewQueue} people={people} onOpen={(id) => navigate(`asset/${id}`)} compact />
				</section>
				<section className="panel deadlines-panel">
					<SectionHeading
						title="Coming up"
						action={
							<span className="subtle-icon">
								<Icon name="clock" size={18} />
							</span>
						}
					/>
					<div className="deadline-list">
						{deadlines.map((asset) => (
							<button className="deadline-item" key={asset.id} onClick={() => navigate(`asset/${asset.id}`)}>
								<span className={`date-block ${new Date(asset.dueAt).getTime() < Date.now() ? "late" : ""}`}>
									<small>{new Date(asset.dueAt).toLocaleDateString("en-US", { month: "short" }).toUpperCase()}</small>
									<strong>{new Date(asset.dueAt).getDate()}</strong>
								</span>
								<span>
									<strong>{asset.title}</strong>
									<small>{asset.projectName}</small>
								</span>
								<Icon name="chevron" size={15} />
							</button>
						))}
						{!deadlines.length && <p className="muted">All caught up. Enjoy a little breathing room.</p>}
					</div>
					<div className="deadline-note">
						<span>✳</span>
						<p>
							A clear deadline makes
							<br />
							room for better work.
						</p>
					</div>
				</section>
			</div>
			<section className="activity-section">
				<SectionHeading title="Around the room" subtitle="The small steps behind the big ideas." />
				<div className="activity-strip">
					{activity.data?.slice(0, 3).map((event) => (
						<button
							className="activity-item"
							key={event.id}
							onClick={() => event.assetId && navigate(`asset/${event.assetId}`)}
						>
							<Avatar user={event.actor} color="lavender" size="small" />
							<div>
								<p>
									<strong>{event.actor?.name || "A teammate"}</strong>{" "}
									{event.description || event.action.replaceAll("_", " ")}
								</p>
								<small>
									{relativeTime(event.createdAt)}
									{event.assetTitle && ` · ${event.assetTitle}`}
								</small>
							</div>
						</button>
					))}
					{!activity.data?.length && <p className="muted">Your workspace activity will appear here.</p>}
				</div>
			</section>
		</>
	);
}
import { useState } from "react";
import Icon from "../../shared/components/Icon";
import { EmptyState } from "../../shared/components/Primitives";
import ProjectCard from "./ProjectCard";

export default function Projects({ projects, people, user, navigate, onCreate }) {
	const [tab, setTab] = useState("active");
	const [query, setQuery] = useState("");
	const visible = projects.filter(
		(project) =>
			(tab === "archived" ? project.archived : !project.archived) && project.name.toLowerCase().includes(query.toLowerCase()),
	);
	return (
		<>
			<div className="page-heading">
				<div>
					<p className="eyebrow">A SHARED SPACE FOR GOOD IDEAS</p>
					<h1>
						Projects in good company<span className="heading-star">✳</span>
					</h1>
					<p>Keep the work, the feedback, and the people together.</p>
				</div>
				{user.role !== "reviewer" && (
					<button className="button primary" onClick={onCreate}>
						<Icon name="plus" size={18} />
						New project
					</button>
				)}
			</div>
			<div className="view-toolbar">
				<div className="tabs">
					<button className={tab === "active" ? "active" : ""} onClick={() => setTab("active")}>
						Active projects <span>{projects.filter((project) => !project.archived).length}</span>
					</button>
					<button className={tab === "archived" ? "active" : ""} onClick={() => setTab("archived")}>
						Archived
					</button>
				</div>
				<label className="inline-search">
					<Icon name="search" size={16} />
					<input
						type="search"
						aria-label="Search projects"
						placeholder="Find a project…"
						value={query}
						onChange={(event) => setQuery(event.target.value)}
					/>
				</label>
			</div>
			<div className="project-grid all-projects">
				{visible.map((project) => (
					<ProjectCard key={project.id} project={project} people={people} onOpen={(id) => navigate(`project/${id}`)} />
				))}
			</div>
			{!visible.length && <EmptyState title="There’s room for something new.">No projects match this view.</EmptyState>}
		</>
	);
}
import { useState } from "react";
import { api } from "../../shared/api/client";
import { AvatarStack, Badge, EmptyState } from "../../shared/components/Primitives";
import Icon from "../../shared/components/Icon";
import Modal from "../../shared/components/Modal";
import Assets from "../assets/Assets";
import ProjectForm from "./ProjectForm";

export default function ProjectDetail({ id, projects, people, user, navigate, onCreate, onChanged, refreshKey, notify, setSearch }) {
	const [editing, setEditing] = useState(false);
	const [archiving, setArchiving] = useState(false);
	const [busy, setBusy] = useState(false);
	const project = projects.find((item) => item.id === id);
	if (!project) return <EmptyState title="This room isn’t available.">It may have been removed, or you may not have access.</EmptyState>;
	const members = people.filter((person) => project.memberIds?.includes(person.id));
	async function archive() {
		setBusy(true);
		try {
			await api(`/projects/${id}`, { method: "PATCH", body: { archived: !project.archived } });
			onChanged();
			setArchiving(false);
			notify(project.archived ? "Your project is back in motion." : "Project archived. Your work is safely kept.");
		} catch (error) {
			notify(error.message, "error");
		} finally {
			setBusy(false);
		}
	}
	return (
		<>
			<button className="text-button back-link" onClick={() => navigate("projects")}>
				<span>←</span>All projects
			</button>
			<div className="page-heading project-detail-heading">
				<div>
					<div className="project-kicker">
						<span style={{ background: project.color }} /> PROJECT <Badge status={project.archived ? "archived" : "active"} />
					</div>
					<h1>{project.name}</h1>
					<p>{project.description}</p>
					<div className="project-members">
						<AvatarStack users={members} />
						<span>{members.length} people bringing this to life</span>
					</div>
				</div>
				{user.role !== "reviewer" && (
					<div className="heading-actions">
						{user.role === "owner" && (
							<button className="button secondary" onClick={() => setEditing(true)}>
								Project settings
							</button>
						)}
						{!project.archived && (
							<button className="button primary" onClick={() => onCreate(id)}>
								<Icon name="plus" size={17} />
								New asset
							</button>
						)}
					</div>
				)}
			</div>
			<Assets
				user={user}
				people={people}
				projects={projects}
				projectId={id}
				navigate={navigate}
				setSearch={setSearch}
				onCreate={() => onCreate(id)}
				refreshKey={refreshKey}
				notify={notify}
			/>
			{user.role === "owner" && (
				<div className="archive-project">
					<p>
						{project.archived
							? "Ready to pick this back up?"
							: "All wrapped up here? Keep your history and clear a little space."}
					</p>
					<button className="text-button" onClick={() => setArchiving(true)}>
						{project.archived ? "Restore project" : "Archive project"}
						<Icon name="arrow" size={15} />
					</button>
				</div>
			)}
			{editing && (
				<ProjectForm
					people={people}
					user={user}
					project={project}
					onClose={() => setEditing(false)}
					onSaved={() => {
						setEditing(false);
						onChanged();
						notify("Project details updated.");
					}}
				/>
			)}
			{archiving && (
				<Modal
					title={project.archived ? "Bring this project back?" : "Wrap up this project?"}
					subtitle="Your assets, feedback, and approval history will stay right here."
					onClose={() => setArchiving(false)}
				>
					<div className="modal-footer">
						<button className="button secondary" onClick={() => setArchiving(false)}>
							Keep as is
						</button>
						<button className="button primary" disabled={busy} onClick={archive}>
							{busy ? "Saving…" : project.archived ? "Restore project" : "Archive project"}
						</button>
					</div>
				</Modal>
			)}
		</>
	);
}
import { useEffect, useState } from "react";
import { api, download } from "../../shared/api/client";
import useResource from "../../shared/api/useResource";
import Icon from "../../shared/components/Icon";
import Modal from "../../shared/components/Modal";
import { Avatar, AvatarStack, Badge, EmptyState, ErrorState, FormField, LoadingState } from "../../shared/components/Primitives";
import { dateLabel, relativeTime, titleCase } from "../../shared/utils/format";
import AssetPreview from "./AssetPreview";
import AssetSettings from "./AssetSettings";
import VersionForm from "./VersionForm";
import Threads from "./Threads";

export default function AssetDetail({ id, user, people, projects, navigate, onChanged, notify }) {
	const resource = useResource(`/assets/${id}`);
	const [version, setVersion] = useState(null);
	const [tab, setTab] = useState("feedback");
	const [anchor, setAnchor] = useState(null);
	const [modal, setModal] = useState("");
	const [note, setNote] = useState("");
	const [busy, setBusy] = useState(false);
	const [error, setError] = useState("");
	useEffect(() => {
		if (resource.data) setVersion(resource.data.version);
	}, [resource.data?.version]);
	useEffect(() => {
		setAnchor(null);
		setError("");
	}, [version, id]);
	async function mutate(path, method, body) {
		try {
			const result = await api(`/assets/${id}${path}`, { method, body });
			resource.setData(result);
			onChanged();
			return result;
		} catch (failure) {
			if (failure.status === 409) {
				resource.refresh();
				notify("This asset changed while you were working. The latest version is loading.", "error");
			}
			throw failure;
		}
	}
	async function submitReview() {
		setBusy(true);
		setError("");
		try {
			await mutate("/submit", "POST", { revision: resource.data.revision });
			notify("Your draft is on its way to the review room.");
		} catch (failure) {
			setError(failure.message);
		} finally {
			setBusy(false);
		}
	}
	async function decision(event) {
		event.preventDefault();
		setBusy(true);
		setError("");
		try {
			await mutate("/decisions", "POST", {
				revision: resource.data.revision,
				version: resource.data.version,
				decision: modal === "approve" ? "approve" : "changes_requested",
				note,
			});
			setModal("");
			setNote("");
			notify(
				modal === "approve"
					? "Your approval is recorded. Good work moves forward."
					: "Your change request is recorded. A clearer next draft is on its way.",
			);
		} catch (failure) {
			setError(failure.message);
		} finally {
			setBusy(false);
		}
	}
	async function exportAsset() {
		try {
			await download(`/assets/${id}/export`, `reviewroom-approved-${id}.json`);
			notify("The approved manifest is ready to share.");
		} catch (failure) {
			notify(failure.message, "error");
		}
	}
	if (resource.loading && !resource.data) return <LoadingState label="Bringing the details into focus…" />;
	if (resource.error) return <ErrorState error={resource.error} retry={resource.refresh} />;
	const asset = resource.data;
	if (!asset) return <EmptyState title="This asset isn’t available." />;
	const selected = asset.versions?.find((item) => item.number === version);
	const current = version === asset.version;
	const stage = asset.stages?.[asset.currentStage || 0];
	const reviewers = people.filter((person) => stage?.reviewerIds?.includes(person.id));
	const members = people.filter((person) => projects.find((project) => project.id === asset.projectId)?.memberIds?.includes(person.id));
	const canEdit = asset.canEdit ?? user.role !== "reviewer";
	return (
		<>
			<button className="text-button back-link" onClick={() => navigate(`project/${asset.projectId}`)}>
				<span>←</span>
				{asset.projectName}
			</button>
			<div className="asset-detail-heading">
				<div>
					<div className="asset-kicker">
						<Icon name={asset.type === "image" ? "image" : "file"} size={15} />
						{asset.type === "image" ? "VISUAL ASSET" : "COPY DOCUMENT"}
						<span>·</span>VERSION {asset.version}
					</div>
					<h1>{asset.title}</h1>
					<div className="asset-meta">
						<Badge status={asset.status} />
						<span>
							<Avatar user={asset.owner} size="tiny" color="peach" />
							{asset.owner?.name}
						</span>
						<span>
							<Icon name="clock" size={14} />
							Due {dateLabel(asset.dueAt)}
						</span>
					</div>
				</div>
				<div className="asset-heading-actions">
					{canEdit && (
						<button className="button secondary" onClick={() => setModal("settings")}>
							<Icon name="people" size={16} />
							Review settings
						</button>
					)}
					{canEdit && (
						<button className="button secondary" onClick={() => setModal("version")}>
							<Icon name="plus" size={16} />
							New version
						</button>
					)}
					{asset.status === "approved" && (
						<button className="button primary" onClick={exportAsset}>
							<Icon name="download" size={16} />
							Export approved
						</button>
					)}
					{canEdit && asset.status === "draft" && (
						<button className="button primary" disabled={busy} onClick={submitReview}>
							<Icon name="arrow" size={16} />
							{busy ? "Submitting…" : "Send for review"}
						</button>
					)}
				</div>
			</div>
			{error && !modal && (
				<p className="form-error" role="alert">
					{error}
				</p>
			)}
			<div className="asset-workflow-bar">
				<div>
					<span className="workflow-symbol">
						<Icon name="review" size={18} />
					</span>
					<div>
						<strong>
							{asset.status === "approved"
								? "A good thing, approved."
								: asset.status === "changes_requested"
									? "A little refinement goes a long way."
									: asset.status === "draft"
										? "Good ideas start somewhere."
										: `${stage?.name || "Review"} is in progress`}
						</strong>
						<span>
							{asset.status === "approved"
								? "Every required stage is complete for this exact version."
								: asset.status === "changes_requested"
									? "Review the feedback, then create a new version."
									: asset.status === "draft"
										? "Check your review stages, then send this draft for feedback."
										: `${stage?.quorum || 1} approval${stage?.quorum === 1 ? "" : "s"} needed · stage ${(asset.currentStage || 0) + 1} of ${asset.stages?.length || 1}`}
						</span>
					</div>
				</div>
				<AvatarStack users={reviewers} />
				{asset.canDecide && current && (
					<div className="decision-buttons">
						<button
							className="button secondary small"
							onClick={() => {
								setModal("changes");
								setError("");
							}}
						>
							Request changes
						</button>
						<button
							className="button approved-button small"
							onClick={() => {
								setModal("approve");
								setError("");
							}}
						>
							<Icon name="check" size={15} />
							Approve
						</button>
					</div>
				)}
			</div>
			<div className="asset-review-layout">
				<div className="asset-preview-column">
					<div className="version-toolbar">
						<label>
							VERSION{" "}
							<select
								aria-label="Select asset version"
								value={version || asset.version}
								onChange={(event) => setVersion(Number(event.target.value))}
							>
								{asset.versions
									?.slice()
									.reverse()
									.map((item) => (
										<option value={item.number} key={item.number}>
											v{item.number}
											{item.number === asset.version ? " — Latest" : ""}
										</option>
									))}
							</select>
						</label>
						{!current && (
