								type="number"
								min="1"
								max={Math.max(1, stage.reviewerIds.length)}
								required
								value={stage.quorum}
								onChange={(event) => update(index, "quorum", Number(event.target.value))}
							/>
						</FormField>
						{stages.length > 1 && (
							<button
								type="button"
								className="icon-button"
								aria-label={`Remove stage ${index + 1}`}
