									onChange={(event) => {
										const ids = event.target.checked
											? [...stage.reviewerIds, person.id]
											: stage.reviewerIds.filter((id) => id !== person.id);
										setStages((previous) =>
											previous.map((item, position) =>
												position === index
													? { ...item, reviewerIds: ids, quorum: Math.min(item.quorum, Math.max(1, ids.length)) }
													: item,
