								maxLength={200}
								placeholder="Separated by commas"
							/>
						</FormField>
					</div>
					{asset.status === "draft" ? (
						<StageEditor
							stages={stages}
							setStages={setStages}
							people={people.filter((person) => person.id !== asset.owner?.id)}
						/>
					) : (
						<div className="locked-stages">
							<strong>Review stages</strong>
							{stages.map((stage, index) => (
								<p key={index}>
									{index + 1}. {stage.name} · {stage.quorum} approval{stage.quorum === 1 ? "" : "s"} required
								</p>
							))}
						</div>
					)}
					{error && (
						<p className="form-error" role="alert">
							{error}
						</p>
					)}
					<p className="form-hint">
						Review stages can change while the asset is a draft. Once submitted, create a new version to change the workflow.
					</p>
				</div>
				<div className="modal-footer">
					<button className="button secondary" type="button" onClick={onClose}>
						Cancel
					</button>
					<button className="button primary" disabled={busy}>
						{busy ? "Saving…" : "Save review settings"}
					</button>
				</div>
			</form>
		</Modal>
	);
}
import { FormField } from "../../shared/components/Primitives";
import Icon from "../../shared/components/Icon";

export default function StageEditor({ stages, setStages, people }) {
	const update = (index, key, value) =>
		setStages((previous) => previous.map((stage, position) => (position === index ? { ...stage, [key]: value } : stage)));
	return (
		<div className="stage-editor">
			<div className="field-heading">
				<span>Review stages</span>
				<button
					type="button"
					className="text-button"
					disabled={stages.length >= 5}
					title="Up to 5 review stages"
					onClick={() =>
						setStages((previous) => [...previous, { name: `Stage ${previous.length + 1}`, reviewerIds: [], quorum: 1 }])
					}
				>
					<Icon name="plus" size={14} />
					Add stage
				</button>
			</div>
			{stages.map((stage, index) => (
				<fieldset className="stage-editor-row" key={index}>
					<legend>Stage {index + 1}</legend>
					<div className="stage-fields">
						<FormField label="Stage name">
							<input
								value={stage.name}
								required
								maxLength={80}
								onChange={(event) => update(index, "name", event.target.value)}
							/>
						</FormField>
						<FormField label="Approvals needed">
							<input
								type="number"
								min="1"
								max={Math.max(1, stage.reviewerIds.length)}
								required
								value={stage.quorum}
								onChange={(event) => update(index, "quorum", Number(event.target.value))}
							/>
						</FormField>
						{stages.length > 1 && (
							<button
								type="button"
								className="icon-button"
								aria-label={`Remove stage ${index + 1}`}
								onClick={() => setStages((previous) => previous.filter((_, position) => position !== index))}
							>
								<Icon name="close" size={16} />
							</button>
						)}
					</div>
					<div className="reviewer-checkboxes">
						{people.map((person) => (
							<label key={person.id}>
								<input
									type="checkbox"
									checked={stage.reviewerIds.includes(person.id)}
									onChange={(event) => {
										const ids = event.target.checked
											? [...stage.reviewerIds, person.id]
											: stage.reviewerIds.filter((id) => id !== person.id);
										setStages((previous) =>
											previous.map((item, position) =>
												position === index
													? { ...item, reviewerIds: ids, quorum: Math.min(item.quorum, Math.max(1, ids.length)) }
													: item,
											),
										);
									}}
								/>
								{person.name}
							</label>
						))}
					</div>
				</fieldset>
			))}
		</div>
	);
}
import { useState } from "react";
import Modal from "../../shared/components/Modal";
import { FormField } from "../../shared/components/Primitives";
import { mediaOptions } from "./AssetForm";

export default function VersionForm({ asset, mutate, onClose }) {
	const [content, setContent] = useState(asset.content || "");
	const [title, setTitle] = useState(asset.title);
	const [mediaPath, setMediaPath] = useState(asset.mediaPath || mediaOptions[0][0]);
	const [note, setNote] = useState("");
	const [busy, setBusy] = useState(false);
	const [error, setError] = useState("");
	async function submit(event) {
		event.preventDefault();
		setBusy(true);
		setError("");
		try {
			await mutate("/versions", "POST", {
				revision: asset.revision,
				title,
				content,
				mediaPath: asset.type === "image" ? mediaPath : "",
				note,
			});
			onClose();
		} catch (failure) {
			setError(failure.message);
		} finally {
			setBusy(false);
		}
	}
	return (
		<Modal
			title={`A fresh take. Version ${asset.version + 1}.`}
			subtitle="Feedback and decisions stay with their original version. The new draft starts with a clean review."
			onClose={onClose}
			wide
		>
			<form onSubmit={submit}>
				<div className="modal-body">
					<FormField label="Asset title">
						<input value={title} required maxLength={160} onChange={(event) => setTitle(event.target.value)} />
					</FormField>
					{asset.type === "image" ? (
						<FormField label="Choose the revised visual">
							<div className="media-picker">
								{mediaOptions.map(([path, label]) => (
									<button
										type="button"
										key={path}
										className={mediaPath === path ? "selected" : ""}
										aria-pressed={mediaPath === path}
										onClick={() => setMediaPath(path)}
									>
										<img src={path} alt={label} loading="lazy" decoding="async" />
									</button>
								))}
							</div>
						</FormField>
					) : (
						<FormField label="Revised content">
							<textarea
								value={content}
								onChange={(event) => setContent(event.target.value)}
								required
								rows={10}
								maxLength={20000}
							/>
						</FormField>
					)}
					<FormField label="What changed?">
						<textarea
							value={note}
							onChange={(event) => setNote(event.target.value)}
							rows={2}
							placeholder="A little context for your reviewers…"
							maxLength={2000}
						/>
					</FormField>
					{error && (
						<p className="form-error" role="alert">
							{error}
						</p>
					)}
				</div>
				<div className="modal-footer">
					<button className="button secondary" type="button" onClick={onClose}>
						Cancel
					</button>
					<button className="button primary" disabled={busy}>
						{busy ? "Saving…" : "Create new version"}
					</button>
				</div>
			</form>
		</Modal>
	);
}
import { Component } from "react";
import { ErrorState } from "./Primitives";

export default class ScreenBoundary extends Component {
	state = { error: null };
	static getDerivedStateFromError(error) {
		return { error };
	}
	render() {
		if (this.state.error) {
			return (
				<ErrorState
					error={{ message: "This screen could not load. Reload to get the latest workspace." }}
					retry={() => window.location.reload()}
				/>
			);
		}
		return this.props.children;
	}
}
